import React, { useCallback } from 'react';
import { chakra, useStyleConfig } from '@chakra-ui/react';
import { defineMessages, useIntl } from 'react-intl';
import { ZimmLink } from 'app/components/ui-kits/atoms/zimmLink';
import { useCartMessages } from 'app/hooks/useCartMessages';
import { usePendingWishlistItem } from './usePendingWishlistItem';
import type { WishlistMoveResult } from './usePendingWishlistItem';

export type { WishlistMoveResult };

const ZIMM_CART_ITEM_ACTIONS_RECIPE = 'ZimmCartItemActions';

// 1:1 Figma-alignment audit fix, 2026-09-21: defaultMessage was 'Move to Wishlist' — confirmed
// against every real cart-item node pulled this session (9323:96527, 9323:101979, 9323:98397,
// 9323:106685), all four show the link's own text as literally "Wishlist". Message id and the
// `moveToWishlist` key are internal identifiers, not user-facing copy — left unchanged.
const messages = defineMessages({
  remove: { id: 'zimm_cart_item_actions.remove', defaultMessage: 'Remove' },
  moveToWishlist: { id: 'zimm_cart_item_actions.move_to_wishlist', defaultMessage: 'Wishlist' },
});

export type ZimmCartItemActionsProps = {
  /** SFCC product id — the stable identity used to match a resumed pending intent across an auth
   *  step, including across a basket merge. See `usePendingWishlistItem`'s own doc for why this
   *  is `productId`, not the line's `itemId`. */
  productId: string;
  /** Interpolated into the wishlist-success toast copy (`useCartMessages.notifyAddedToWishlist`)
   *  — never hardcoded at a call site. */
  productName: string;
  /**
   * Whether the current shopper is unauthenticated. Read once by the caller (e.g. from
   * `useCustomerType()`) and passed down as a plain prop, rather than this component calling
   * that hook itself — see this file's own architecture note below for why.
   */
  isGuest: boolean;
  /**
   * Removes this entire line (all units) from the cart — a single call, never looped, regardless
   * of the line's current quantity (SFCC-270 AC8 / SFCC-272 AC3). The actual SFCC
   * `removeItemFromBasket` call is the caller's own responsibility (SFCC-11 plan step 4.6,
   * `cartDrawerContainer.tsx`, not built yet) — this component only ever calls this prop once per
   * click, and again (at most once) if a wishlist move succeeds.
   */
  onRemove: () => void | Promise<void>;
  /**
   * Attempts the real wishlist-add for an authenticated shopper. The actual SDK call is the
   * caller's own responsibility (step 4.6) — this component only calls it and reacts to the
   * result. Resolves to a discriminated union so this component can choose the right feedback
   * without any data-fetching of its own — see `WishlistMoveResult`'s own doc.
   */
  onMoveToWishlist: () => Promise<WishlistMoveResult>;
  /**
   * Called when a guest clicks "Wishlist" for this row, after the pending intent has
   * already been persisted (see `usePendingWishlistItem`). The caller is responsible for opening
   * the one shared wishlist auth drawer — see this file's own architecture note for why this
   * component does not open it directly.
   */
  onGuestWishlistClick: () => void;
  /**
   * 1:1 Figma-alignment audit fix, 2026-09-22: called when `attemptMoveToWishlist` resolves
   * `'already-in-wishlist'`, alongside — not instead of — the existing `notifyAlreadyInWishlist()`
   * toast below. This component's own result branching is otherwise invisible to its parent: the
   * caller owns `ProductItem`'s `message` slot (cart-line inline status, SFCC-795 §11.2) and needs
   * to know this specific line just got this result to show it there. Optional so every existing
   * caller from before this prop existed keeps working unchanged, with only the toast firing.
   */
  onAlreadyInWishlist?: () => void;
};

/**
 * Molecule — the "Remove" / "Wishlist" action links rendered below a cart line's quantity
 * stepper (SFCC-270 AC8, SFCC-272). Supplied by the caller into base `product-item`'s own
 * `secondaryActions` slot (already wired, `overrides/app/components/product-item/index.tsx:365`)
 * — this molecule does not inject itself into that structure, it is simply the node passed in.
 *
 * Architecture note — why this component does not call `useWishlistAuthDrawer` itself, despite
 * that hook being an auth-gating hook rather than a data-fetching one (so calling it from a
 * `ui-kits/` component is not, by itself, a `components.md` container/presentational violation —
 * `ZimmWishlistAuthDrawer`, `overrides/app/components/ui-kits/organisms/zimmWishlistAuthDrawer/
 * index.tsx:35-58`, is the existing precedent for exactly that). The SFCC-11 plan requires exactly
 * ONE `useWishlistAuthDrawer` instance for the whole cart (`intentId: 'cart-wishlist'`), and
 * explicitly rejects mounting one instance per line item — a multi-item bag would mount a
 * `useForm`, three `useAuthHelper`s, a `useAuthModal` and a drawer per row. Because this component
 * is itself rendered once per cart line (one per `secondaryActions` slot), calling that hook
 * directly here would reproduce exactly the rejected per-row shape. So the one real hook instance
 * must live above every row — the cart container, SFCC-11 plan step 4.6, not yet built — and this
 * component receives `isGuest` / `onGuestWishlistClick` as plain props instead, wired by that
 * container to its own single hoisted `handleTriggerClick`. `useCartMessages` below has no such
 * constraint: it is a stateless wrapper around Chakra's own `useToast()`
 * (`overrides/app/hooks/useCartMessages.ts`), safe to call from as many rendered instances as
 * there are cart lines — this divergence from a literal per-row hook call is deliberate and
 * disclosed in this step's own report, not silently resolved.
 *
 * @param props see ZimmCartItemActionsProps
 */
export const ZimmCartItemActions = ({
  productId,
  productName,
  isGuest,
  onRemove,
  onMoveToWishlist,
  onGuestWishlistClick,
  onAlreadyInWishlist,
}: ZimmCartItemActionsProps) => {
  const intl = useIntl();
  const styles = useStyleConfig(ZIMM_CART_ITEM_ACTIONS_RECIPE);
  const { notifyAddedToWishlist, notifyAlreadyInWishlist } = useCartMessages();

  // Shared by both the direct (already-authenticated) click path below and the post-auth resume
  // path (usePendingWishlistItem's onResume) — one implementation of "branch on the move result",
  // not two copies of the same logic.
  const attemptMoveToWishlist = useCallback(async () => {
    const result = await onMoveToWishlist();
    if (result.status === 'success') {
      await onRemove();
      notifyAddedToWishlist(productName);
    } else if (result.status === 'already-in-wishlist') {
      notifyAlreadyInWishlist();
      onAlreadyInWishlist?.();
    }
    // 'error': no AC or Figma copy exists for this branch — leave the item in the cart and emit
    // no message rather than invent feedback text (same "do not invent copy" principle the
    // SFCC-11 plan applies to its own unspecified error feedback elsewhere, e.g. step 5.1).
  }, [onMoveToWishlist, onRemove, notifyAddedToWishlist, notifyAlreadyInWishlist, productName, onAlreadyInWishlist]);

  const { beginPendingMove } = usePendingWishlistItem({
    productId,
    isGuest,
    onResume: attemptMoveToWishlist,
  });

  const handleWishlistClick = () => {
    if (isGuest) {
      beginPendingMove();
      onGuestWishlistClick();
      return;
    }
    void attemptMoveToWishlist();
  };

  return (
    <chakra.div __css={styles}>
      <ZimmLink size="small" label={intl.formatMessage(messages.remove)} onClick={() => void onRemove()} />
      <ZimmLink size="small" label={intl.formatMessage(messages.moveToWishlist)} onClick={handleWishlistClick} />
    </chakra.div>
  );
};

import { useEffect, useState } from 'react';
import {
  clearSessionJSONItem,
  getSessionJSONItem,
  setSessionJSONItem,
} from '@salesforce/retail-react-app/app/utils/utils';

/**
 * Outcome of one wishlist-move attempt. The actual SFCC SDK calls (wishlist add + cart removal)
 * are the caller's own responsibility — SFCC-11 plan step 4.6 (`cartDrawerContainer.tsx`, not
 * built yet) — this file only reports what happened, matching the exact discriminated-union
 * pattern `useCartMergeAndCap.ts`'s own `CartCapResult` already established
 * (`overrides/app/hooks/useCartMergeAndCap.ts:25-29`), per typescript.md's stated preference for
 * a discriminated union over a pile of optional fields.
 */
export type WishlistMoveResult =
  | { status: 'success' }
  | { status: 'already-in-wishlist' }
  | { status: 'error'; error: unknown };

/**
 * sessionStorage key PREFIX for "a guest asked to move THIS specific cart line to their wishlist
 * before authenticating." Namespaced per `productId` — see `pendingWishlistCartItemKey` below —
 * so that two different cart rows' pending intents can never collide in a single shared slot: a
 * guest beginning a pending move on row A, then row B, before either completes a redirect-based
 * auth flow, must leave both independently resumable rather than row B's write silently
 * overwriting row A's. Deliberately a distinct mechanism, and a distinct key, from
 * `useWishlistAuthDrawer.ts`'s own `PENDING_WISHLIST_INTENT_KEY`
 * (`overrides/app/hooks/useWishlistAuthDrawer.ts:43`): that key answers "which mounted drawer
 * instance's `onAuthSuccess` should fire after a social-IDP redirect" — its own
 * `PendingWishlistIntent` type carries only `intentId`/`timestamp`, no item identity at all.
 * This hook answers a different question — "which cart LINE was pending" — so it is a new,
 * separate mechanism rather than an addition to that shared type. The SFCC-11 plan explicitly
 * rejects adding an `itemId` field to that shared type: it has three other existing call sites
 * (header/rightBar, drawer-menu, product-view) and changing it is out of this step's scope.
 */
const PENDING_WISHLIST_CART_ITEM_KEY_PREFIX = 'zimmPendingWishlistCartItem';

/**
 * Builds the per-product sessionStorage key — see `PENDING_WISHLIST_CART_ITEM_KEY_PREFIX`'s own
 * doc for why storage is namespaced this way instead of one shared key.
 */
const pendingWishlistCartItemKey = (productId: string): string =>
  `${PENDING_WISHLIST_CART_ITEM_KEY_PREFIX}:${productId}`;

/**
 * Same 5-minute bound as `useWishlistAuthDrawer.ts`'s own `PENDING_WISHLIST_INTENT_MAX_AGE_MS`
 * (`overrides/app/hooks/useWishlistAuthDrawer.ts:52` — `5 * 60 * 1000`), and the same reasoning:
 * long enough for a real auth round trip, short enough that a long-abandoned attempt cannot
 * misfire later against a much later, unrelated cart session. Not imported from that file — the
 * constant is not exported there, and this step does not modify that file (out of scope; see the
 * SFCC-11 plan step 4.4's manifest and its "explicitly rejected" list). Redefined here as an
 * independent, same-valued constant instead.
 */
const PENDING_WISHLIST_MAX_AGE_MS = 5 * 60 * 1000; // 5 minutes

type PendingWishlistCartItem = {
  /**
   * Matched against this row's own `productId`, not `itemId` — deliberate. A guest's basket may
   * be merged into a registered customer's basket between the guest's click and the shopper
   * completing auth (SFCC-250 step 4.1, `useWishlistAuthDrawer.ts`'s own `isRegistered` effect),
   * and that merge can change which `itemId` a given product line carries (it merges into a
   * destination basket via `createDestinationBasket: true`). `productId` is stable across that
   * boundary; `itemId` is not — keying the match on `itemId` would risk silently failing to
   * resume a legitimate pending move the moment a merge has actually happened. See this step's
   * own report for the related, still-open sequencing question this raises for step 4.6.
   */
  productId: string;
  timestamp: number;
};

export type UsePendingWishlistItemParams = {
  /** Identifies this cart line for matching a resumed intent — see PendingWishlistCartItem's own
   *  doc comment for why this is `productId`, not `itemId`. */
  productId: string;
  /** Whether the current shopper is unauthenticated. Passed down from the caller (e.g. read once
   *  from `useCustomerType()` at the cart container) rather than read by this hook itself — see
   *  `zimmCartItemActions/index.tsx`'s own architecture note for why. */
  isGuest: boolean;
  /** Called (no arguments) once a previously-pending move for THIS row should be attempted.
   *  Fires at most once per stored intent — never for another row's pending item, never twice
   *  for the same one. */
  onResume: () => void | Promise<void>;
};

export type UsePendingWishlistItemReturn = {
  /** Call when a guest clicks "Wishlist" for this row — persists the pending intent to
   *  both React state (survives the email-code/create-account flows, which never unload the
   *  page) and session storage (survives the Apple/Google redirect, which reloads it), so
   *  `onResume` fires automatically once `isGuest` becomes false for this same product. */
  beginPendingMove: () => void;
};

/**
 * Hook — persists a guest's "move to wishlist" intent for one cart line across an authentication
 * step, and resumes it once the shopper is no longer a guest. Extracted per
 * `.claude/rules/components.md`'s extract-to-hook threshold: this is React state plus a
 * non-trivial effect (session-storage read/write/clear, a 5-minute age check, resuming after a
 * simulated page reload) that would otherwise sit inline in `ZimmCartItemActions`.
 *
 * Deliberately calls no auth or `commerce-sdk-react` hook itself — `isGuest` arrives as a plain
 * prop, and the actual move (`onResume`) is the caller's own already-composed function. Only ONE
 * `useWishlistAuthDrawer` instance may exist for the whole cart (SFCC-11 plan step 4.4's own
 * explicit rejection of "one per line item"), so that real hook cannot live inside a component
 * that mounts once per cart line — this hook stays calling-hook-free so it can safely mount once
 * per row, alongside it, without reproducing that rejected shape.
 *
 * @returns `beginPendingMove`, the one function a guest click calls.
 */
export const usePendingWishlistItem = ({
  productId,
  isGuest,
  onResume,
}: UsePendingWishlistItemParams): UsePendingWishlistItemReturn => {
  const [pending, setPending] = useState<PendingWishlistCartItem | undefined>(undefined);

  const beginPendingMove = () => {
    const intent: PendingWishlistCartItem = { productId, timestamp: Date.now() };
    setPending(intent);
    setSessionJSONItem(pendingWishlistCartItemKey(productId), intent);
  };

  // Mirrors useWishlistAuthDrawer.ts's own redirect-consuming effect (that file's second
  // useEffect, [isRegistered]-only deps, overrides/app/hooks/useWishlistAuthDrawer.ts:252-259) —
  // runs on mount and on every `isGuest` change, not only on a true-to-false transition, because
  // a fresh mount after a real page reload (Apple/Google redirect) already has `isGuest === false`
  // on its very first render, with no transition to observe.
  useEffect(() => {
    if (isGuest) return;

    const stored = getSessionJSONItem(pendingWishlistCartItemKey(productId)) as PendingWishlistCartItem | undefined;
    // The per-product key above already means `stored` can only ever be what THIS row itself
    // wrote — a different row's pending intent lives under its own, different key and is never
    // read, resumed, or cleared from here. This productId match is a defensive belt-and-suspenders
    // check on top of that (never act on foreign/malformed data even if it somehow ended up in
    // this slot), not the mechanism that keeps two rows apart.
    const mineFromStorage = stored?.productId === productId ? stored : undefined;
    const candidate = pending ?? mineFromStorage;
    if (!candidate) return;

    // Found something of mine — clear both stores now, regardless of whether it turns out to be
    // fresh or stale below (a stale intent must not linger either — nothing resumes it later).
    // Only ever clears THIS row's own key — another row's still-pending intent, under its own
    // key, is untouched.
    setPending(undefined);
    clearSessionJSONItem(pendingWishlistCartItemKey(productId));

    const isFresh = Date.now() - candidate.timestamp <= PENDING_WISHLIST_MAX_AGE_MS;
    if (isFresh) {
      void onResume();
    }
  }, [isGuest]);

  return { beginPendingMove };
};

